#!/bin/bash
# Run `lake comparator` (bundled with Lean since 4.35) against all three challenge/solution pairs:
#   config.json      — 13 architecture-free theorems, Challenge imports only Mathlib
#   config-arch.json — 39 architecture theorems, ChallengeArch imports the project
#   config-tier.json — the tie / faithfulness / whole-net / DP / float / certificate
#                      theorems, machine-generated by scripts/gates/gen_comparator_tier.py.
#                      This is exactly formalization.yaml's advertised set minus the
#                      ones config-arch.json already covers, so the three files together
#                      kernel-recheck every declaration the project puts forward.
#
# What it verifies, per config:
#   1. Solution's theorem statements match Challenge's (the prover didn't redefine the goal).
#   2. Each proof's transitive axiom closure is a subset of
#      [propext, Quot.sound, Classical.choice] — i.e. zero project axioms.
#   3. The proof typechecks against Lean's kernel — and, with --paranoid (the default here),
#      against every independent checker the toolchain bundles: leanchecker-paranoid,
#      lean4lean, nanoda, con-leche and con-ron.
#
# The six modules are the root package's `ComparatorTests` lib (see lakefile.lean): Lake builds
# and exports them inside a `bwrap` sandbox that can read only the project directory, so they
# cannot live in a nested package that path-requires `../..`.
#
# Prerequisites: Lean ≥ 4.35 (the project toolchain), `bwrap` (bubblewrap) on PATH with user
# namespaces available, and the project's oleans warm (`lake build Certs`), or the sandboxed
# build compiles the corpus itself. See README.md.
#
# Usage: tests/comparator/run.sh [--no-paranoid]

set -e

PARANOID=--paranoid
[ "$1" = "--no-paranoid" ] && PARANOID=

cd "$(dirname "$0")/../.."

# One `[comparator] <config>: <n> theorems OK in <s> s` line per config, printed only after
# `lake comparator` exits 0 (set -e). comparator.yml's job summary is built from these lines.
for cfg in config.json config-arch.json config-tier.json; do
  path="tests/comparator/$cfg"
  n="$(python3 -c 'import json, sys; print(len(json.load(open(sys.argv[1]))["theorem_names"]))' "$path")"
  t0=$SECONDS
  lake comparator $PARANOID --config "$path"
  echo "[comparator] $cfg: $n theorems OK in $((SECONDS - t0)) s"
done
